import { describe, expect, it } from 'vitest'
import { createToolResultMessage, createUserMessage, freezeMessage, ToolCallId, type Message } from '@deepseek-ai/dsh-llm'
import { Session, SessionId, SessionSeq } from '@deepseek-ai/dsh-session'
import type { SessionMessageProjection } from '@deepseek-ai/dsh-session/surface'
import { activityFact, activityText } from '../src/activity-facts.ts'
import { AGENT_TEAM_PLUGIN_ID } from '../src/context-source.ts'
import { isFactOnSurface, isMainEntryOnSurface, teamMessageSurface, visibleTeamSurface } from '../src/surface-visibility.ts'
import type {
  AgentTeamActivity,
  AgentTeamMainActivity,
  AgentTeamMainTimelineEntry,
  AgentTeamProjectRef,
  AgentTeamThreadReadFact,
  AgentTeamThreadRef,
} from '../src/types.ts'
import { teamTools } from '../../tool-agent-team/tests/render-text.ts'

const THREAD = 'thread:alpha' as AgentTeamThreadRef
const OTHER_THREAD = 'thread:beta' as AgentTeamThreadRef
const PROJECT = 'project:alpha' as AgentTeamProjectRef

declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    'test/prune-team-fact': { readonly seq: number; readonly text: string }
  }
}

const prune: SessionMessageProjection<'test/prune-team-fact'> = {
  type: 'test/prune-team-fact',
  project(event, context) {
    const seq = SessionSeq(event.data.seq)
    const source = context.events[seq - context.baseSeq]
    const message = context.messages.get(seq) ?? (source?.type === 'tool/result' ? source.data.message : source?.type === 'user/message' ? source.data : undefined)
    return new Map<SessionSeq, Message>(message === undefined ? [] : [[seq, freezeMessage({ ...message, content: [{ type: 'text', text: event.data.text }] })]])
  },
}

function session() {
  return Session.create(SessionId('session:surface-probe'), undefined, undefined, undefined, [prune])
}

function factOf(body: string, messageRef = 'message:a'): AgentTeamThreadReadFact {
  return { fact: { kind: 'message', sequence: 12, message: { messageRef, body } as never, mentions: [], occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: true }
}

function result(target: Session, body: string, threadRef = THREAD, messageRef = 'message:a', name = 'team_message') {
  const tool = teamTools().get('team_message')!
  const args = { action: 'reply', threadRef, body: 'response', baseRevision: 10 }
  const value = { kind: 'unread_required', threadRef, revision: 12, unreadCount: 1, directCount: 0,
    facts: [{ kind: 'message', sequence: 12, sender: 'human', messageRef, body }] }
  const callId = ToolCallId(`call:${target.snapshotEvents().length}`)
  const call = target.append('tool/call', { turn: 1, step: 1, callId, name, arguments: JSON.stringify(args) })
  return target.append('tool/result', { turn: 1, step: 1,
    message: createToolResultMessage({ callId, content: tool.output.render(args, value), isError: false }),
    meta: tool.output.presentationMeta!(args, value),
  }, { surfaceOp: 'append', sourceEventSeqs: [call.seq] })
}

function sees(target: Session, body: string, threadRef = THREAD, messageRef = 'message:a') {
  return isFactOnSurface(visibleTeamSurface({ session: target }), factOf(body, messageRef), threadRef)
}

function threadClaim(overrides: Record<string, unknown> = {}): AgentTeamActivity {
  return {
    activityRef: 'activity:shared', taskRef: 'task:a', threadRef: THREAD, actor: 'member:builder',
    sequence: 12, kind: 'claim', claimRef: 'claim:a', ...overrides,
  } as unknown as AgentTeamActivity
}

function mainOwnerActivity(overrides: Record<string, unknown> = {}): AgentTeamMainActivity {
  return {
    activityRef: 'activity:shared', projectRef: PROJECT, kind: 'owner-added', memberId: 'member:b',
    actor: 'human', sequence: 5, occurredAt: '2026-10-14T00:00:00.000Z', ...overrides,
  } as unknown as AgentTeamMainActivity
}

function activityReadFact(activity: AgentTeamActivity): AgentTeamThreadReadFact {
  return ({ fact: { kind: 'activity', sequence: activity.sequence, activity, occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: false } as AgentTeamThreadReadFact)
}

function mainActivityEntry(activity: AgentTeamMainActivity): AgentTeamMainTimelineEntry {
  return { kind: 'activity', sequence: activity.sequence, activity, occurredAt: activity.occurredAt, unread: true, direct: false }
}

function activityResult(target: Session, activity: AgentTeamActivity | AgentTeamMainActivity, name = 'team_thread') {
  const fact = activityFact(activity)
  const text = activityText(fact)
  const callId = ToolCallId(`call:${target.snapshotEvents().length}`)
  const call = target.append('tool/call', { turn: 1, step: 1, callId, name, arguments: '{}' })
  return target.append('tool/result', { turn: 1, step: 1,
    message: createToolResultMessage({ callId, content: [{ type: 'text', text }], isError: false }),
    meta: { teamFacts: teamMessageSurface(text, [], [fact]) },
  }, { surfaceOp: 'append', sourceEventSeqs: [call.seq] })
}

describe('only complete Team-sourced facts on the current Session surface satisfy the gate', () => {
  it('recognizes an actual rendered rejection, with the exact Thread, Message and body', () => {
    const target = session()
    result(target, 'ok')
    expect(sees(target, 'ok')).toBe(true)
    expect(sees(target, 'ok', OTHER_THREAD)).toBe(false)
    expect(sees(target, 'ok', THREAD, 'message:b')).toBe(false)
    expect(sees(target, 'OK')).toBe(false)
    expect(sees(target, 'o')).toBe(false)
  })

  it('rejects a projected summary that retains meta and repeats the same short body', () => {
    const target = session()
    const original = result(target, 'ok')
    target.append('test/prune-team-fact', { seq: original.seq, text: 'Summary: ok\n' })
    expect(original.data.message.content[0]).toMatchObject({ text: expect.stringContaining('ok') })
    expect(target.deriveEventMessage(original)?.content[0]).toMatchObject({ text: 'Summary: ok\n' })
    expect(sees(target, 'ok')).toBe(false)
  })

  it('does not borrow the same text from a different Message after cropping', () => {
    const target = session()
    const first = result(target, 'ok')
    target.append('test/prune-team-fact', { seq: first.seq, text: '[removed]' })
    result(target, 'ok', THREAD, 'message:b')

import { describe, expect, it, vi } from 'vitest'
// These boot real Hosts over throwaway trees; the same 30s headroom the
// Thread-read progress suite uses for cold replays applies here.
vi.setConfig({ testTimeout: 30_000 })
import { agentTeamHumanActor, isThreadReadSnapshot } from '../src/ledger.ts'
import { STALLED_PUBLIC_MS } from '../src/task-reminders.ts'
import type { AgentTeamOperation, AgentTeamThreadReadOperation, AgentTeamThreadReadReceipt } from '../src/types.ts'
import { addLedgerMember, alpha, committed, harness, ledgerAtBoot, makeOwner, requestId, storedPool, withTask, type TeamHarness } from './helpers/host-harness.ts'

/** Every durable Thread-read record in the harness's operation table, in ledger order. */
function readOperations(test: TeamHarness): readonly AgentTeamThreadReadOperation[] {
  return [...test.facility.get('agent_team')!.table('operations').entries()]
    .map(([, operation]) => operation as AgentTeamOperation)
    .filter((operation): operation is AgentTeamThreadReadOperation => operation.kind === 'team/thread-read')
}

function receiptOf(operation: AgentTeamThreadReadOperation): AgentTeamThreadReadReceipt {
  if (isThreadReadSnapshot(operation.data)) throw new Error('expected the slim receipt form')
  return operation.data
}

function operationTableSize(test: TeamHarness): number {
  return test.facility.get('agent_team')!.table('operations').size
}

/**
 * One Task Thread with a Human opening, a Member reader following it, and five
 * replies after the follow: ordinary, mention, ordinary, mention, ordinary.
 * The two mentions give the reader two sparse direct markers inside one batch.
 */
async function seededReaderThread() {
  const test = await harness()
  const project = await test.ctx.agentTeam.createProject({ requestId: requestId('project'), workspaceId: alpha,
    name: 'engineering', description: 'Engineering work' })
  const sent = withTask(committed(await test.ctx.agentTeam.startThread({ kind: 'task', requestId: requestId('start'),
    workspaceId: alpha, projectRef: project.project.projectRef, body: 'Investigate the regression' })))
  const ledger = ledgerAtBoot(test)
  const reader = await addLedgerMember(ledger, project.project.projectRef, 'member:reader', 'Reader agent', 'reader')
  const human = agentTeamHumanActor()
  await ledger.changeAttention({ requestId: requestId('follow-reader'), workspaceId: alpha,
    taskRef: sent.task.taskRef, action: 'follow', actor: reader.actor })
  let revision = sent.thread.revision
  const replies: Array<{ readonly sequence: number; readonly body: string }> = []
  for (const body of ['first update', '@reader second update', 'third update', '@reader fourth update', 'fifth update']) {
    const replied = committed((await ledger.reply({ requestId: requestId(`reply-${body}`), workspaceId: alpha,
      taskRef: sent.task.taskRef, body, baseRevision: revision, actor: human })).value)
    replies.push({ sequence: replied.message.sequence, body })
    revision = replied.thread.revision
  }
  return { test, ledger, reader, sent, replies, revision }
}

/**
 * One in-progress Task with a stalled reminder still unread for its
 * accountable Member, plus one ordinary reply the Member has not read. The
 * Member is the Task accountable and a Project owner, so the reminder targets
 * exactly the reader under test.
 */
async function seededReminderThread() {
  const test = await harness()
  const project = await test.ctx.agentTeam.createProject({ requestId: requestId('project'), workspaceId: alpha,
    name: 'delivery', description: 'Delivery work' })
  const ledger = ledgerAtBoot(test)
