/**
 * Resolve and validate all metadata from the adapter that owns one exact
 * route. The result is detached from adapter-owned objects; catalog
 * membership remains advisory and does not control request routing.
 * @param provider - registered provider route to inspect.
 * @param model - exact model id passed to the adapter.
 * @param signal - optional cancellation for adapter-owned asynchronous lookup.
 * @returns exact model identity plus available context and reasoning metadata.
 */
async resolveModelInfo(
  provider: string,
  model: string,
  signal?: AbortSignal,
): Promise<LlmResolvedModelInfo> {
  return this.resolveModelInfoFor(this.registration(provider), model, signal)
}

private async resolveModelInfoFor(
  registration: AdapterRegistration,
  model: string,
  signal?: AbortSignal,
): Promise<LlmResolvedModelInfo> {
  const resolved = await registration.adapter.resolveModel(registration.provider.id, model, signal)
  return this.normalizeModelInfo(registration, model, resolved)
}

/** Validate and detach one adapter-returned exact model result. */
private normalizeModelInfo(
  registration: AdapterRegistration,
  model: string,
  resolved: LlmResolvedModelInfo,
): LlmResolvedModelInfo {
  const provider = registration.provider.id
  if (
    typeof resolved.provider !== 'string'
    || resolved.provider !== provider
    || typeof resolved.id !== 'string'
    || resolved.id !== model
    || typeof resolved.name !== 'string'
    || resolved.name.length === 0
    || (resolved.description !== undefined && typeof resolved.description !== 'string')
  ) {
    throw new LlmError(
      `adapter returned invalid exact model metadata for provider "${provider}" model "${model}"`,
      'INVALID_MODEL_INFO',
    )
  }
  const context = resolved.context
  if (context !== undefined && (!Number.isInteger(context.contextWindow) || context.contextWindow <= 0)) {
    throw new LlmError(
      `adapter returned invalid context metadata for provider "${provider}" model "${model}"`,
      'INVALID_MODEL_CONTEXT',
    )
  }

  models[0]!.name = 'mutated'
  provider.name = 'source mutated'
  model.name = 'source mutated'
  expect(ctx.llm.listProviders()).toEqual([{ id: 'catalog', name: 'Catalog Provider' }])
  await expect(ctx.llm.listModels('catalog')).resolves.toEqual([{
    provider: 'catalog', id: 'fast', name: 'source mutated', description: 'Low latency', inputModalities: ['text'],
  }])
})

